class TMP102_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x0000,  # TEMP
            0x01: 0x60A0,  # CONFIG
            0x02: 0x4B00,  # TLOW
            0x03: 0x5000   # THIGH
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if nbytes == 1:
            return (self.regs[addr] >> 8) & 0xFF
