        if addr == 0x00:  # TEMP is read-only
            return
        if nbytes == 1:
            current_value = self.regs[addr]
            data <<= 8
            self.regs[addr] = (current_value & 0xFF) | data
        elif nbytes == 2:
            self.regs[addr] = data
        else:
            raise ValueError("Invalid nbytes for write")

