class TMP102_Simulator(BaseVirtualSensor):
    REG_TEMP = 0x00
    REG_CONFIG = 0x01
    REG_TLOW = 0x02
    REG_THIGH = 0x03

    def __init__(self):
        super().__init__()
        self.regs[self.REG_TEMP] = 0x0000  # 0°C
        self.regs[self.REG_CONFIG] = 0x60A0  # Default configuration
        self.regs[self.REG_TLOW] = 0x4B00  # Low threshold 75°C
        self.regs[self.REG_THIGH] = 0x5000  # High threshold 80°C

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if addr == self.REG_TEMP:
            # Read-only register, ignore write
            return

        if nbytes == 1:
            mask = 0xFF << 8
            data <<= 8
        else:
            mask = 0xFFFF

        current_value = self.regs[addr]
        new_value = (current_value & ~mask) | (data & mask)
        self.regs[addr] = new_value

